import{_ as n,o as a,c as i,ag as p}from"./chunks/framework.PVHj0As1.js";const e="/pub-blog/assets/wps19.CQjIxmBq.jpg",l="/pub-blog/assets/wps20.tGVuGwOs.jpg",r="/pub-blog/assets/wps21.B-l3Z9SM.jpg",t="/pub-blog/assets/wps22.C1kRs7Fx.jpg",h="/pub-blog/assets/wps23.Blp27zX3.jpg",o="/pub-blog/assets/wps24.5KNcjyXS.jpg",c="/pub-blog/assets/wps25.BhTPV68G.jpg",b="/pub-blog/assets/wps26.BwVeGthJ.jpg",d="/pub-blog/assets/wps27.B0KyH4MF.jpg",f=JSON.parse('{"title":"AI 玩转鸿蒙（3）：语法错误全自动修复，小白也能上手","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/AI 玩转鸿蒙/AI 玩转鸿蒙 （3）：语法错误全自动修复，小白也能上手/AI 玩转鸿蒙 （3）：语法错误全自动修复，小白也能上手.md","filePath":"鸿蒙开发技巧/AI 玩转鸿蒙/AI 玩转鸿蒙 （3）：语法错误全自动修复，小白也能上手/AI 玩转鸿蒙 （3）：语法错误全自动修复，小白也能上手.md","lastUpdated":1768277828000,"__rawMarkdown":"# AI 玩转鸿蒙（3）：语法错误全自动修复，小白也能上手\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：[https://blog.zbztb.cn/](https://blog.zbztb.cn/)\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n>\\n> 最近我在B站上进行不定期的免费鸿蒙技术直播，欢迎关注：[https://space.bilibili.com/414874315?spm_id_from=333.33.0.0](https://space.bilibili.com/414874315?spm_id_from=333.33.0.0)\\n\\n> 配套视频：https://www.bilibili.com/video/BV1qer6B2EbZ/#reply115885784239939\\n\\n## 前言：AI 提效，让开发更轻松\\n\\n去年在参加激励赛期间，我所有的应用都是用 AI 完成的。在企业上班的同时，我采用\\"AI 编程 + 自己忙一些事\\"的并行方式，真正体验到了技术带来的便利和收益！\\n\\n## 一、痛点：AI 编辑器开发鸿蒙代码，经常有语法错误\\n\\n使用 AI 编辑器开发鸿蒙应用时，经常会遇到各种语法错误：\\n\\n使用 TypeScript 语法导致错误、函数签名用错\\n\\n手动复制错误信息给 AI 工具，整个过程体验很差，效率低下。\\n\\n通过配置，在 AI 编辑器中实现：**一次对话，做到语法不出错（即使出错了，也能自动修复）**\\n\\n---\\n\\n## 二、选择合适的 AI 编辑器工具\\n\\nClaude + Code：Token 费用高 + 中转问题、海外版 Trae + Gemini-3-Pro\\n\\n\\n\\n---\\n\\n## 三、项目规则：让 AI 更懂你的项目\\n\\n不同的 AI 编辑器都有自己生成项目规则的做法，一般都是在工程内新建 MD 规则文件。\\n\\n### Trae 规则文件\\n\\n![img](assets/wps19.jpg)\\n\\n### Qoder 规则文件\\n\\n![img](assets/wps20.jpg)\\n\\n### 我的规则文件（重点）\\n\\n规则文件的作用至关重要，特别是**开发约定**部分。\\n\\n以下是流蓝卡片项目的规则文件示例：\\n\\n```markdown\\n# FlowCard - HarmonyOS 应用项目\\n\\n## 项目概述\\n这是一个基于 **HarmonyOS NEXT (API 21)** 开发的手机应用项目，使用 **ArkTS** 语言和 **ArkUI** 声明式框架构建。项目采用 Stage 模型，是 HarmonyOS 新一代应用开发架构。\\n\\n### 技术栈\\n- **开发语言**: ArkTS (TypeScript 的超集)\\n- **UI 框架**: ArkUI (声明式 UI)\\n- **构建工具**: Hvigor\\n- **目标平台**: HarmonyOS 6.0.1 (API 21)\\n- **设备类型**: 手机 (phone)\\n- **应用类型**: Stage 模型应用\\n\\n### 项目信息\\n- **Bundle Name**: `liulankapian.qinglanzhuma.huawei`\\n- **版本**: 1.0.0 (versionCode: 1000000)\\n- **主入口**: EntryAbility\\n- **主页面**: Index.ets\\n\\n## 项目结构\\n\\n```\\n```\\nflowCard/\\n├── AppScope/              # 应用全局配置\\n│   ├── app.json5          # 应用配置文件\\n│   └── resources/         # 应用级资源\\n├── entry/                 # 主模块\\n│   ├── src/main/\\n│   │   ├── ets/\\n│   │   │   ├── entryability/     # 应用入口能力\\n│   │   │   │   └── EntryAbility.ets\\n│   │   │   ├── entrybackupability/  # 备份恢复能力\\n│   │   │   │   └── EntryBackupAbility.ets\\n│   │   │   └── pages/            # 页面文件\\n│   │   │       └── Index.ets     # 首页\\n│   │   ├── resources/            # 模块资源文件\\n│   │   └── module.json5          # 模块配置\\n│   ├── src/ohosTest/             # 自动化测试\\n│   └── src/test/                 # 单元测试\\n├── hvigor/                       # 构建配置\\n├── build-profile.json5           # 构建配置文件\\n├── hvigorfile.ts                 # Hvigor 构建脚本\\n└── oh-package.json5              # 依赖管理文件\\n\\n\\n\\n\\n\\n\\n## 构建和运行\\n\\n### 前置要求\\n- 安装 DevEco Studio (推荐最新版本)\\n- 配置 HarmonyOS SDK 6.0.1 或更高版本\\n- 配置签名证书 (真机运行需要)\\n\\n\\n\\n\\n## 开发约定\\n\\n### 代码风格\\n- 使用 **ArkTS** 语言规范\\n- 采用声明式 UI 编程范式\\n- 组件使用 `@ComponentV2` 装饰器\\n\\n### 状态管理（重要！）\\n⚠️ **重要约束**: 本项目只能使用 **V2 状态管理技术**，禁止使用 V1 状态管理\\n\\n**使用 V2 装饰器:**\\n- `@ObservedV2`\\n- `@Trace`\\n- `@ComponentV2`\\n- `@Local`\\n- `@Param`\\n\\n**禁止使用 V1 装饰器:**\\n- `@State`\\n- `@Prop`\\n- `@Link`\\n- `@Provide`\\n- `@Consume`\\n```\\n\\n![img](assets/wps21.jpg)\\n\\n![img](assets/wps22.jpg)\\n\\n---\\n\\n## 四、必备工具介绍\\n\\n### hdc 工具\\n\\nhdc（HarmonyOS Device Connector）是提供给开发人员的命令行调试工具，用于与设备进行交互调试、数据传输、日志查看以及应用安装等操作。该工具支持在 Windows/Linux/MacOS 系统上运行，为开发者提供高效、便捷的设备调试能力。\\n\\n[官方文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/hdc)\\n\\n![img](assets/wps23.jpg)\\n\\n### hvigorw\\n\\nhvigorw 作为 Hvigor 的 wrapper 包装工具，支持自动安装 Hvigor 构建工具和相关插件依赖，以及执行 Hvigor 构建命令。\\n\\n[官方文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-hvigor-commandline)\\n\\n![img](assets/wps24.jpg)\\n\\n---\\n\\n## 五、实战演示：自动识别并修复语法错误\\n\\n\\n\\n配置好证书（手动签名/自动签名），可以让程序运行在模拟器或者真机上。\\n\\n让 AI 编辑器根据当前系统生成构建-运行程序的脚本。\\n\\n![img](assets/wps25.jpg)\\n\\n### 演示使用\\n\\n![img](assets/wps26.jpg)\\n\\n### 自动构建-发现错误-自动修复\\n\\n![img](assets/wps27.jpg)\\n\\n###  通过项目规则管理流程\\n\\n将上述流程纳入项目规则管理：\\n\\n```json\\n{\\n  \\"项目规则\\": {\\n    \\"1\\": \\"使用之前的项目规则文件\\",\\n    \\"2\\": \\"每一次生成代码完毕后，都要主动调用构建脚本 install.ps1 来构建和修复程序\\",\\n    \\"3\\": \\"当构建脚本 install.ps1 检查没有错误了，就自动提交到 git\\"\\n  }\\n}\\n\\n```\\n\\n---\\n\\n## 六、下期预告\\n\\n**如何极速接入云端能力**\\n\\n### 华为鸿蒙 - 端云一体能力\\n\\n### 腾讯 CodeBuddy 内置 CloudBase\\n\\n- 操作云端数据库\\n- 后端接口对接\\n\\n让应用从单机升级为联网应用！\\n\\n---\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](https://wsy996.obs.cn-east-3.myhuaweicloud.com/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.jpg)\\n\\n"}'),k={name:"鸿蒙开发技巧/AI 玩转鸿蒙/AI 玩转鸿蒙 （3）：语法错误全自动修复，小白也能上手/AI 玩转鸿蒙 （3）：语法错误全自动修复，小白也能上手.md"};function g(u,s,m,E,y,w){return a(),i("div",null,[...s[0]||(s[0]=[p("",59)])])}const _=n(k,[["render",g]]);export{f as __pageData,_ as default};
